import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

const canvas=document.querySelector('#game');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
const scene=new THREE.Scene();scene.background=new THREE.Color(0x071318);scene.fog=new THREE.Fog(0x071318,60,145);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,220);
scene.add(new THREE.HemisphereLight(0xbdeeff,0x243b2c,2.1));
const keyLight=new THREE.DirectionalLight(0xe4ffff,3.3);keyLight.position.set(-25,38,19);keyLight.castShadow=true;keyLight.shadow.mapSize.set(2048,2048);keyLight.shadow.camera.left=-60;keyLight.shadow.camera.right=60;keyLight.shadow.camera.top=65;keyLight.shadow.camera.bottom=-65;scene.add(keyLight);
const rimLight=new THREE.DirectionalLight(0xff9a5c,1.5);rimLight.position.set(24,18,-20);scene.add(rimLight);
const mat=(color,roughness=.55,metalness=0,emissive=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness,emissive,emissiveIntensity:emissive?1.4:0});
const M={grass:mat(0x235c50,.92),grass2:mat(0x296657,.93),line:mat(0x9be8d6,.55,0,.2),dark:mat(0x101b22,.72),wall:mat(0x142932,.45,.2),white:mat(0xf4f3e7,.3),ball:mat(0xf6f5ec,.32,.08),blue:mat(0x1ba9f1,.28,.35,0x0872b6),blueTrim:mat(0x7be8ff,.28,.4,0x23afd6),orange:mat(0xff7c29,.27,.25,0xbb4810),orangeTrim:mat(0xffd070,.3,.2,0xc26c17),tire:mat(0x11151a,.82),glass:mat(0x122b35,.18,.52),gold:mat(0xffce4c,.27,.2,0x805000)};
function box(parent,x,y,z,sx,sy,sz,material,cast=true){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.castShadow=cast;m.receiveShadow=true;parent.add(m);return m}
function sphere(parent,x,y,z,r,material,segments=20){const m=new THREE.Mesh(new THREE.SphereGeometry(r,segments,segments),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function cylinder(parent,x,y,z,r1,r2,h,material,segments=12){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material);m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m}
function makeArena(){
 const floor=new THREE.Mesh(new THREE.PlaneGeometry(72,100),M.grass);floor.rotation.x=-Math.PI/2;floor.position.y=-.15;floor.receiveShadow=true;scene.add(floor);
 for(let i=0;i<10;i++){let stripe=new THREE.Mesh(new THREE.PlaneGeometry(7.2,100),i%2?M.grass:M.grass2);stripe.rotation.x=-Math.PI/2;stripe.position.set(-32.4+i*7.2,-.14,.02);scene.add(stripe)}
 const circle=new THREE.Mesh(new THREE.RingGeometry(9.8,10,.5,96),M.line);circle.rotation.x=-Math.PI/2;circle.position.y=-.05;scene.add(circle);
 const mid=new THREE.Mesh(new THREE.RingGeometry(.35,.52,32),M.line);mid.rotation.x=-Math.PI/2;mid.position.y=-.045;scene.add(mid);
 for(let z of [-35,35]){box(scene,0,-.045,z,70,.04,.16,M.line,false);for(let x of [-23,23]){const arc=new THREE.Mesh(new THREE.RingGeometry(9.8,10,.5,64,0,Math.PI),M.line);arc.rotation.x=-Math.PI/2;arc.position.set(x,-.04,z<0?z+35:z-35);scene.add(arc)}}
 // Low glass sideboards and end walls
 for(let x of [-36,36]){box(scene,x,1,0,1.2,2,94,M.wall);for(let z=-42;z<=42;z+=14){const post=box(scene,x,2.5,z,.35,3.2,.35,M.blueTrim);post.material=x<0?M.blueTrim:M.orangeTrim}}
 for(let z of [-48,48]){box(scene,0,1,z,72,2,1.2,M.wall);for(let x=-32;x<=32;x+=16)box(scene,x,2.3,z,.35,3,.35,M.blueTrim)}
 // goals: open mouth with glowing frame
 for(let side of [-1,1]){const z=side*47.25,goalMat=side<0?M.orangeTrim:M.blueTrim;box(scene,-9,3.1,z,.45,6.2,.5,goalMat);box(scene,9,3.1,z,.45,6.2,.5,goalMat);box(scene,0,6.1,z,18,.45,.5,goalMat);const net=mat(side<0?0x3c1f1a:0x123148,.9,0,.08);box(scene,0,2.9,z-side*3,18,.08,6,net,false);for(let x=-8;x<=8;x+=2)box(scene,x,2.9,z-side*3,.035,5.6,.035,goalMat,false);for(let y=.4;y<6;y+=1)box(scene,0,y,z-side*3,18,.025,.025,goalMat,false)}
 // Stadium stands and floodlights
 for(let side of [-1,1]){for(let row=0;row<5;row++){const bench=box(scene,side*40,3.2+row*1.35,0,7,1.1,100,mat(row%2?0x183541:0x1d3d47,.78));bench.position.x=side*40}for(let z of [-38,0,38]){const pole=cylinder(scene,side*41,10,z,.22,.35,18,M.dark);const lamp=box(scene,side*41,19,z,5,.28,1.4,mat(0xe8ffff,.2,0,0xbafaff));const glow=new THREE.PointLight(0x79dfff,48,38,2);glow.position.set(side*38,18,z);scene.add(glow)}}
 for(let z of [-48,48]){for(let x of [-29,29]){cylinder(scene,x,10,z,.18,.3,18,M.dark);box(scene,x,19,z,5,.25,1.3,mat(0xffd8b8,.2,0,0xffb875));const l=new THREE.PointLight(0xffad6b,30,30,2);l.position.set(x,18,z);scene.add(l)}}
 // Distant audience pixels around the rim
 const crowdMats=[0x4ca3b1,0xf5a05c,0x5477a7,0xd4e7d0,0x72528e].map(c=>mat(c,.75,0,c));
 for(let i=0;i<220;i++){const a=i/220*Math.PI*2;const radius=47+Math.random()*5;const px=Math.cos(a)*radius,pz=Math.sin(a)*radius*1.34;const h=1+Math.random()*2.2;const c=new THREE.Mesh(new THREE.BoxGeometry(.4,h,.4),crowdMats[i%crowdMats.length]);c.position.set(px,2+h/2,pz);scene.add(c)}
}
makeArena();
function makeCar(color,trim){const g=new THREE.Group();const chassis=box(g,0,.72,0,2.15,.62,3.65,color);chassis.geometry.translate(0,0,0);box(g,0,1.23,.12,1.55,.62,1.75,M.glass);box(g,0,1.02,-1.05,1.95,.22,.62,trim);box(g,0,.55,-1.88,1.75,.2,.24,trim);for(let x of [-1.12,1.12])for(let z of [-1.15,1.15]){const w=cylinder(g,x,.49,z,.48,.48,.32,M.tire,16);w.rotation.x=Math.PI/2;const hub=cylinder(g,x,.49,z-.18,.21,.21,.03,trim,12);hub.rotation.x=Math.PI/2}for(let x of [-.68,.68]){const light=box(g,x,.83,-1.85,.32,.16,.08,M.white,false);light.material=mat(0xffffff,.2,0,0xffffff)}const flameMat=new THREE.MeshBasicMaterial({color:0x35d8ff,transparent:true,opacity:.8});const flame=new THREE.Mesh(new THREE.ConeGeometry(.38,1.25,12),flameMat);flame.rotation.x=Math.PI/2;flame.position.set(0,.66,2.25);g.add(flame);flame.visible=false;g.userData.flame=flame;g.userData.wheels=[];return g}
const player={mesh:makeCar(M.blue,M.blueTrim),pos:new THREE.Vector3(0,0,21),vel:new THREE.Vector3(),yaw:0,boost:100,air:0,airVel:0,stun:0,item:null,drift:0};player.mesh.position.copy(player.pos);scene.add(player.mesh);
const bot={mesh:makeCar(M.orange,M.orangeTrim),pos:new THREE.Vector3(0,0,-22),vel:new THREE.Vector3(),yaw:Math.PI,stun:0,think:0};bot.mesh.position.copy(bot.pos);scene.add(bot.mesh);
// Ball with a subtle luminous shadow
const ball=sphere(scene,0,1.45,0,1.42,M.ball,32);ball.material=mat(0xe7ede9,.24,.14);const ballLines=mat(0x293d43,.55);for(let i=0;i<3;i++){let ring=new THREE.Mesh(new THREE.TorusGeometry(1.43,.045,5,50),ballLines);ring.rotation.set(Math.PI/2*(i%2),i*Math.PI/3,0);ball.add(ring)}
const ballShadow=new THREE.Mesh(new THREE.CircleGeometry(1.8,32),new THREE.MeshBasicMaterial({color:0x061013,transparent:true,opacity:.44}));ballShadow.rotation.x=-Math.PI/2;ballShadow.position.y=-.08;scene.add(ballShadow);
const ballState={pos:new THREE.Vector3(0,1.45,0),vel:new THREE.Vector3(),spin:0};
// Power-up boxes
const itemTypes={shell:{name:'HOMING SHELL',icon:'🐚',color:0x49e1a1},banana:{name:'BANANA PEEL',icon:'🍌',color:0xffdd3e},turbo:{name:'MEGA TURBO',icon:'⚡',color:0x53d9ff},lightning:{name:'LIGHTNING',icon:'ϟ',color:0xf7a7ff}};
const pickups=[];const pickupSpots=[[-16,9],[16,9],[-16,-9],[16,-9],[0,0]];
function makePickup(x,z,index){const g=new THREE.Group();const cube=box(g,0,0,0,1.45,1.45,1.45,mat(0xffce4c,.28,.25,0xffaa17));const inner=box(g,0,0,0,.75,.75,.75,mat(0xfff3b4,.2,.1,0xffea7a),false);const edges=new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(1.5,1.5,1.5)),new THREE.LineBasicMaterial({color:0xffffff}));g.add(edges);g.position.set(x,1.35,z);scene.add(g);const light=new THREE.PointLight(0xffc64a,5,8,2);g.add(light);pickups.push({group:g,active:true,index,baseY:1.35,respawn:0})}
pickupSpots.forEach((p,i)=>makePickup(p[0],p[1],i));
const projectiles=[];const bananas=[];const particles=[];
function burst(pos,color,count=14){for(let i=0;i<count;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.09+Math.random()*.09,7,7),new THREE.MeshBasicMaterial({color,transparent:true}));m.position.copy(pos);scene.add(m);particles.push({mesh:m,vel:new THREE.Vector3((Math.random()-.5)*8,Math.random()*7,(Math.random()-.5)*8),life:.55+Math.random()*.45})}}
function announce(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');clearTimeout(announce.timer);announce.timer=setTimeout(()=>t.classList.remove('show'),1500)}
function feed(text){const e=document.createElement('div');e.className='feed-entry';e.innerHTML=text;document.querySelector('#event-feed').prepend(e);setTimeout(()=>e.remove(),3400)}
function setItem(type){player.item=type;const o=itemTypes[type];document.querySelector('#item-name').textContent=o.name;document.querySelector('#item-slot').innerHTML=`<span style="filter:drop-shadow(0 0 8px #fff)">${o.icon}</span>`;document.querySelector('#item-panel').style.borderColor='#'+o.color.toString(16).padStart(6,'0')}
function clearItem(){player.item=null;document.querySelector('#item-name').textContent='NO ITEM';document.querySelector('#item-slot').innerHTML='<span class="item-empty">?</span>';document.querySelector('#item-panel').style.borderColor='rgba(255,255,255,.2)'}
function useItem(){if(!running||!player.item)return;const type=player.item;clearItem();if(type==='turbo'){player.boost=Math.min(100,player.boost+55);player.vel.addScaledVector(forward(player.yaw),19);burst(player.pos.clone().add(new THREE.Vector3(0,.6,0)),0x51efff,24);announce('MEGA TURBO!');feed('<b>BOOST BURST</b> — GO GO GO');}
 if(type==='lightning'){bot.stun=2.8;bot.vel.multiplyScalar(.2);burst(bot.pos.clone().add(new THREE.Vector3(0,2,0)),0xc68cff,26);announce('LIGHTNING STRIKE!');feed('<b>LIGHTNING</b> — RIVAL ZAPPED');}
 if(type==='shell'){const s=sphere(scene,player.pos.x,.8,player.pos.z, .55,mat(0x35de92,.2,.2,0x27da7e),16);s.userData.direction=forward(player.yaw).multiplyScalar(23);s.userData.life=4;s.userData.homing=1;projectiles.push(s);announce('SHELL AWAY!');feed('<b>HOMING SHELL</b> — INCOMING!');}
 if(type==='banana'){const b=sphere(scene,player.pos.x,.35,player.pos.z, .48,mat(0xffdf37,.4,0,0xe9a900),12);b.scale.set(.55,.55,1.5);b.userData.life=12;bananas.push(b);announce('BANANA DEPLOYED');feed('<b>BANANA PEEL</b> — WATCH YOUR STEP');}}
function forward(yaw){return new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw))}
const keys={};let running=false,paused=false,remaining=120,blueScore=0,orangeScore=0,previous=performance.now(),goalFlash=0;
function resetPositions(){player.pos.set(0,0,21);player.vel.set(0,0,0);player.yaw=0;player.air=0;player.airVel=0;player.mesh.position.copy(player.pos);player.mesh.rotation.set(0,0,0);bot.pos.set(0,0,-22);bot.vel.set(0,0,0);bot.yaw=Math.PI;bot.mesh.position.copy(bot.pos);ballState.pos.set(0,1.45,0);ballState.vel.set(0,0,0);ball.position.copy(ballState.pos)}
function score(team){if(team==='blue'){blueScore++;document.querySelector('#blue-score').textContent=blueScore;announce('GOAL! BLUE ROCKETS SCORE');feed('<b>GOAL!</b> BLUE ROCKETS');}else{orangeScore++;document.querySelector('#orange-score').textContent=orangeScore;announce('ORANGE COMETS SCORE');feed('<b>GOAL!</b> ORANGE COMETS');}goalFlash=.75;burst(ballState.pos.clone(),team==='blue'?0x43caff:0xff873b,45);resetPositions()}
function finish(){running=false;document.querySelector('#result-title').textContent=blueScore===orangeScore?'IT’S A DRAW':blueScore>orangeScore?'VICTORY!':'MATCH LOST';document.querySelector('#result-copy').textContent=`BLUE ${blueScore}  —  ${orangeScore} ORANGE`;document.querySelector('#result-overlay').classList.remove('hidden')}
function startGame(){blueScore=orangeScore=0;remaining=120;document.querySelector('#blue-score').textContent='0';document.querySelector('#orange-score').textContent='0';document.querySelector('#clock').textContent='2:00';document.querySelector('#result-overlay').classList.add('hidden');document.querySelector('#start-overlay').classList.add('hidden');clearItem();resetPositions();running=true;announce('KICKOFF!');}
document.querySelector('#play-button').addEventListener('click',startGame);document.querySelector('#rematch-button').addEventListener('click',startGame);
document.querySelector('#sound-btn').addEventListener('click',()=>{const l=document.querySelector('.sound-label');l.textContent=l.textContent==='SOUND ON'?'SOUND OFF':'SOUND ON';document.querySelector('#sound-icon').textContent=l.textContent==='SOUND ON'?'♪':'×'});
function clampCar(car){car.pos.x=THREE.MathUtils.clamp(car.pos.x,-33,33);car.pos.z=THREE.MathUtils.clamp(car.pos.z,-43.5,43.5)}
function drive(car,dt,steer,throttle,boosting=false){const f=forward(car.yaw);const speed=car.vel.dot(f);const turn=2.25*Math.min(1,Math.abs(speed)/4+.18);car.yaw+=steer*turn*dt*(speed<-.5?-1:1);const dir=forward(car.yaw);if(throttle>0)car.vel.addScaledVector(dir,24*throttle*dt);if(throttle<0)car.vel.addScaledVector(dir,18*throttle*dt);if(boosting){car.vel.addScaledVector(dir,33*dt);car.mesh.userData.flame.visible=true}else car.mesh.userData.flame.visible=false;const drag=Math.exp(-1.5*dt);car.vel.multiplyScalar(drag);const max=boosting?31:21;if(car.vel.length()>max)car.vel.setLength(max);car.pos.addScaledVector(car.vel,dt);clampCar(car);car.mesh.position.set(car.pos.x,car.air,car.pos.z);car.mesh.rotation.y=car.yaw;car.mesh.rotation.z=car.drift*-.13;}
function collBall(car,power=1){const center=new THREE.Vector3(car.pos.x,.78+car.air,car.pos.z);const delta=ballState.pos.clone().sub(center);const d=delta.length();if(d<2.8){if(d<.001)delta.set(0,0,-1);delta.normalize();const speed=Math.max(9,car.vel.length()*1.05);ballState.vel.addScaledVector(delta,speed*power);ballState.vel.addScaledVector(car.vel,.48);ballState.vel.y=Math.max(ballState.vel.y,2.4+Math.max(0,car.air)*2);const f=forward(car.yaw);ballState.vel.addScaledVector(f,4.2);ballState.pos.addScaledVector(delta,2.8-d+.03);}}
function updateBot(dt){if(bot.stun>0){bot.stun-=dt;bot.vel.multiplyScalar(Math.exp(-4*dt));bot.pos.addScaledVector(bot.vel,dt);bot.mesh.position.set(bot.pos.x,0,bot.pos.z);return}const target=ballState.pos.clone().setY(0);if(Math.abs(target.z+45)<8)target.x*=.5;const dx=target.x-bot.pos.x,dz=target.z-bot.pos.z;const desired=Math.atan2(-dx,-dz);let delta=((desired-bot.yaw+Math.PI*3)%(Math.PI*2))-Math.PI;const steer=THREE.MathUtils.clamp(delta*2.7,-1,1);const dist=Math.hypot(dx,dz);const throttle=dist>2.8?1:.15;drive(bot,dt,steer,throttle,false);if(dist<3.1)collBall(bot,1.05)}
function updateItems(dt){for(const p of pickups){p.group.rotation.y+=dt*1.1;p.group.position.y=p.baseY+Math.sin(performance.now()*.0018+p.index)*.2;if(!p.active){p.respawn-=dt;if(p.respawn<=0){p.active=true;p.group.visible=true}continue}if(!player.item&&Math.hypot(player.pos.x-p.group.position.x,player.pos.z-p.group.position.z)<2.1){p.active=false;p.group.visible=false;p.respawn=8;const kinds=Object.keys(itemTypes);setItem(kinds[Math.floor(Math.random()*kinds.length)]);announce('POWER-UP ACQUIRED');feed(`<b>${itemTypes[player.item].name}</b> — PRESS Q`);burst(p.group.position,0xffd352,14)}}
 for(let i=projectiles.length-1;i>=0;i--){const s=projectiles[i];s.userData.life-=dt;const target=bot.pos.clone().sub(s.position).setY(0).normalize();s.userData.direction.lerp(target.multiplyScalar(24),dt*1.2).normalize().multiplyScalar(23);s.position.addScaledVector(s.userData.direction,dt);s.rotation.x+=dt*4;s.rotation.y+=dt*6;if(s.position.distanceTo(bot.pos.clone().add(new THREE.Vector3(0,.8,0)))<2){bot.stun=1.6;burst(s.position,0x3eff9d,19);scene.remove(s);projectiles.splice(i,1);announce('SHELL HIT!');continue}if(s.userData.life<=0){scene.remove(s);projectiles.splice(i,1)}}
 for(let i=bananas.length-1;i>=0;i--){const b=bananas[i];b.userData.life-=dt;b.rotation.y+=dt*1.5;if(b.position.distanceTo(bot.pos.clone().setY(.35))<1.6){bot.stun=2;bot.vel.multiplyScalar(.1);burst(b.position,0xffdf37,15);scene.remove(b);bananas.splice(i,1);announce('RIVAL SLIPPED!');continue}if(b.userData.life<=0){scene.remove(b);bananas.splice(i,1)}}
 for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.vel.y-=13*dt;p.mesh.position.addScaledVector(p.vel,dt);p.mesh.material.opacity=Math.max(0,p.life);if(p.life<=0){scene.remove(p.mesh);particles.splice(i,1)}}}
function updateBall(dt){ballState.vel.y-=16*dt;ballState.pos.addScaledVector(ballState.vel,dt);if(ballState.pos.y<1.42){ballState.pos.y=1.42;if(ballState.vel.y<0)ballState.vel.y*=-.62;ballState.vel.x*=Math.exp(-.32*dt);ballState.vel.z*=Math.exp(-.32*dt);if(Math.abs(ballState.vel.y)<.8)ballState.vel.y=0}if(ballState.pos.x>34.5||ballState.pos.x< -34.5){ballState.pos.x=THREE.MathUtils.clamp(ballState.pos.x,-34.5,34.5);ballState.vel.x*=-.75}if(Math.abs(ballState.pos.z)>46.5&&Math.abs(ballState.pos.x)>9){ballState.pos.z=Math.sign(ballState.pos.z)*46.5;ballState.vel.z*=-.72}if(Math.abs(ballState.pos.z)>48&&Math.abs(ballState.pos.x)<9&&ballState.pos.y<6){score(ballState.pos.z>0?'blue':'orange');return}if(Math.abs(ballState.pos.z)>47&&ballState.pos.y>6){ballState.pos.z=Math.sign(ballState.pos.z)*47;ballState.vel.z*=-.8}if(ballState.pos.y>13){ballState.pos.y=13;ballState.vel.y*=-.7}ballState.vel.multiplyScalar(Math.exp(-.18*dt));ball.rotation.x+=ballState.vel.z*dt*.36;ball.rotation.z-=ballState.vel.x*dt*.36;ball.position.copy(ballState.pos);ballShadow.position.x=ballState.pos.x;ballShadow.position.z=ballState.pos.z;ballShadow.material.opacity=Math.max(.12,.48-ballState.pos.y*.025)}
const camTarget=new THREE.Vector3(),camPos=new THREE.Vector3();
function updateCamera(dt){const f=forward(player.yaw);camTarget.set(player.pos.x,1.2+player.air,player.pos.z).addScaledVector(f,7);camPos.set(player.pos.x,0,player.pos.z).addScaledVector(f,-12);camPos.y=7.6+player.air*.55;camera.position.lerp(camPos,1-Math.exp(-4.3*dt));const look=ballState.pos.clone().lerp(camTarget,.65);camera.lookAt(look);}
function update(dt){if(running){remaining-=dt;if(remaining<=0){remaining=0;finish()}const steer=(keys.a||keys.arrowleft?1:0)-(keys.d||keys.arrowright?1:0);const throttle=(keys.w||keys.arrowup?1:0)-(keys.s||keys.arrowdown?1:0);const boosting=(keys.shift||keys.shiftleft||keys.shiftright)&&player.boost>0&&throttle>=0;if(boosting)player.boost=Math.max(0,player.boost-35*dt);else player.boost=Math.min(100,player.boost+8*dt);player.drift=steer*Math.abs(player.vel.dot(forward(player.yaw)))/21;drive(player,dt,steer,throttle,boosting);player.airVel-=18*dt;player.air+=player.airVel*dt;if(player.air<0){player.air=0;player.airVel=0}if(player.air>4){player.air=4;player.airVel=Math.min(0,player.airVel)}collBall(player,1.1);updateBot(dt);collBall(bot,1);updateBall(dt);updateItems(dt);document.querySelector('#boost-fill').style.width=player.boost+'%';document.querySelector('#boost-value').textContent=Math.round(player.boost);document.querySelector('#speed-value').textContent=String(Math.round(player.vel.length()*8)).padStart(3,'0');const sec=Math.ceil(remaining);document.querySelector('#clock').textContent=`${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`;if(goalFlash>0)goalFlash-=dt}
 updateCamera(dt);}
function frame(now){const dt=Math.min(.04,(now-previous)/1000);previous=now;update(dt);renderer.render(scene,camera);requestAnimationFrame(frame)}
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});
