document.querySelectorAll('.touch-controls [data-key]').forEach(btn=>{const key=btn.dataset.key;btn.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true;btn.setPointerCapture(e.pointerId);if(key==='space'&&running&&player.air===0){player.airVel=8.5;player.air+=.08}if(key==='q')useItem()});const off=e=>{e.preventDefault();keys[key]=false};btn.addEventListener('pointerup',off);btn.addEventListener('pointercancel',off);btn.addEventListener('lostpointercapture',()=>keys[key]=false)});
